/**
 * winget manifests for a published release, from its checksums.txt. Nothing is
 * rebuilt: the installer is the release's tracetoon-skill-windows-x64.zip (the
 * skill with the Windows binary in bin/), installed as a portable command.
 *
 *   bun .github/scripts/winget-manifest.ts <checksums.txt> <tag> <out>
 *
 * writes manifests/t/Tracetoon/Tracetoon/<version>/ in the winget-pkgs layout:
 * the version, installer and defaultLocale files of a multi-file manifest
 * (https://learn.microsoft.com/windows/package-manager/package/manifest), schema
 * 1.12.0 (https://github.com/microsoft/winget-pkgs/tree/master/doc/manifest/schema/1.12.0).
 * An archive installer needs NestedInstallerType, and a portable nested file can
 * carry a PortableCommandAlias (installer.md in that schema folder).
 * docs/release-channels.md says how they reach microsoft/winget-pkgs.
 */
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { readChecksums, releaseVersion } from './release-assets.ts';
import { RELEASES } from './homebrew-formula.ts';

export const IDENTIFIER = 'Tracetoon.Tracetoon';
const SCHEMA = '1.12.0';
const ASSET = 'tracetoon-skill-windows-x64.zip';

const q = (s: string) => JSON.stringify(s); // a YAML double-quoted scalar
const header = (type: string) =>
  `# Generated by .github/scripts/winget-manifest.ts. Do not edit.\n` +
  `# yaml-language-server: $schema=https://aka.ms/winget-manifest.${type}.${SCHEMA}.schema.json\n`;

export function wingetManifests(checksums: string, tag: string): Record<string, string> {
  const version = releaseVersion(tag);
  const sha256 = readChecksums(checksums).get(ASSET);
  if (!sha256) throw Error(`checksums.txt has no ${ASSET}.`);
  const id = `PackageIdentifier: ${IDENTIFIER}\nPackageVersion: ${q(version)}\n`;
  const footer = (type: string) => `ManifestType: ${type}\nManifestVersion: ${SCHEMA}\n`;
  return {
    [`${IDENTIFIER}.yaml`]:
      header('version') + id + `DefaultLocale: en-US\n` + footer('version'),
    [`${IDENTIFIER}.installer.yaml`]:
      header('installer') +
      id +
      `InstallerType: zip\n` +
      `NestedInstallerType: portable\n` +
      `NestedInstallerFiles:\n` +
      `- RelativeFilePath: ${q('tracetoon\\bin\\tracetoon-windows-x64.exe')}\n` +
      `  PortableCommandAlias: tracetoon\n` +
      `Commands:\n- tracetoon\n` +
      `Installers:\n` +
      `- Architecture: x64\n` +
      `  InstallerUrl: ${RELEASES}/${tag}/${ASSET}\n` +
      `  InstallerSha256: ${sha256.toUpperCase()}\n` +
      footer('installer'),
    [`${IDENTIFIER}.locale.en-US.yaml`]:
      header('defaultLocale') +
      id +
      `PackageLocale: en-US\n` +
      `Publisher: Tracetoon\n` +
      `PublisherUrl: https://tracetoon.ai\n` +
      `PublisherSupportUrl: https://github.com/Tracetoon/tracetoon/issues\n` +
      `PackageName: Tracetoon\n` +
      `PackageUrl: https://github.com/Tracetoon/tracetoon\n` +
      `License: Apache-2.0\n` +
      `LicenseUrl: https://github.com/Tracetoon/tracetoon/blob/main/LICENSE\n` +
      `ShortDescription: ${q("Write pull request descriptions from coding agents' session logs.")}\n` +
      `Description: ${q(
        'Tracetoon writes GitHub pull request descriptions from the session logs coding agents keep on disk, checks every claim against that evidence, and can add a one-off comic. Run `tracetoon setup` to add its skill to your agents.',
      )}\n` +
      `Moniker: tracetoon\n` +
      `Tags:\n- ai-agents\n- cli\n- github\n- pull-request\n` +
      `ReleaseNotesUrl: https://github.com/Tracetoon/tracetoon/releases/tag/${tag}\n` +
      footer('defaultLocale'),
  };
}

/** Writes the manifests under `out` in the winget-pkgs layout; returns their paths. */
export function writeWingetManifests(
  checksums: string,
  tag: string,
  out: string,
): string[] {
  const dir = join(out, 'manifests', 't', 'Tracetoon', 'Tracetoon', releaseVersion(tag));
  mkdirSync(dir, { recursive: true });
  return Object.entries(wingetManifests(checksums, tag)).map(([name, text]) => {
    writeFileSync(join(dir, name), text);
    return join(dir, name);
  });
}

if (import.meta.main) {
  const [checksums, tag, out] = process.argv.slice(2);
  if (!checksums || !tag || !out)
    throw Error('Use: winget-manifest.ts <checksums.txt> <tag> <out>');
  for (const p of writeWingetManifests(readFileSync(checksums, 'utf8'), tag, out))
    console.log(p);
}
